package com.personal.tasklist;

import static org.junit.Assert.*;
import android.app.*;
import android.content.*;
import java.time.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.shadows.ShadowSystemClock;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class TaskVisibilityTest {
    Context context;ReferenceStore store;String date;long now;
    @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("reference_state",0).edit().clear().commit();context.getSharedPreferences("tasks",0).edit().clear().commit();TaskReminders.prefs(context).edit().clear().commit();ZonedDateTime target=ZonedDateTime.now(ReminderPlanner.ZONE).plusDays(1).withHour(10).withMinute(0).withSecond(0).withNano(0);ShadowSystemClock.advanceBy(Duration.ofMillis(target.toInstant().toEpochMilli()-System.currentTimeMillis()));store=new ReferenceStore(context);now=System.currentTimeMillis();date=Instant.ofEpochMilli(now).atZone(ReminderPlanner.ZONE).toLocalDate().toString();assertEquals(10,Instant.ofEpochMilli(now).atZone(ReminderPlanner.ZONE).getHour());}
    JSONObject task(String id,String time,int lead)throws Exception{return new JSONObject().put("id",id).put("title",id).put("due",date).put("time",time).put("showBeforeMinutes",lead).put("priority","LOW").put("labels",new JSONArray().put("Visibility QA"));}
    JSONObject record(JSONObject task)throws Exception{String key=task.getString("id")+":"+date;return new JSONObject().put("id","html:"+key).put("title",task.getString("title")).put("dueDate",date).put("plannedDate",date).put("done",false).put("createdAt",42).put("labels",task.getJSONArray("labels")).put("status",TaskStore.NEXT).put("priority","LOW").put("minutes",0).put("progressKey",key).put("stateDate",date).put("snapshotDate",date).put("onToday",true).put("completionKeys",new JSONArray().put(key)).put("time",task.getString("time")).put("showBeforeMinutes",task.getInt("showBeforeMinutes"));}
    @Test public void revealTimeMatchesDueTimeAndDaylightSavingRules()throws Exception{
        JSONObject task=task("clock","2:00 PM",90);assertEquals(Instant.parse("2026-11-04T17:30:00Z").toEpochMilli(),TaskVisibility.showAt(task,"2026-11-04"));task.put("time","1:30 AM").put("showBeforeMinutes",0);assertEquals(Instant.parse("2026-11-01T05:30:00Z").toEpochMilli(),TaskVisibility.showAt(task,"2026-11-01"));task.put("time","2:30 AM").put("showBeforeMinutes",30);assertEquals(Instant.parse("2026-03-08T07:00:00Z").toEpochMilli(),TaskVisibility.showAt(task,"2026-03-08"));task.put("time","1:00 AM").put("showBeforeMinutes",120);assertEquals(Instant.parse("2026-11-05T04:00:00Z").toEpochMilli(),TaskVisibility.showAt(task,"2026-11-05"));
    }
    @Test public void widgetKeepsHiddenRowsAndRevealsThemAtTheBoundary()throws Exception{
        JSONObject a=task("later","12:00 PM",30),b=task("latest","1:00 PM",30);store.writeState(new JSONObject().put("customTasks",new JSONArray().put(a).put(b)).put("reminders",new JSONObject().put("daily",false).put("scheduled",false)).toString());store.updateSnapshot(new JSONArray().put(record(a)).put(record(b)).toString());assertEquals(0,TaskWidgetProvider.todayTasks(context,"","Visibility QA").size());assertEquals(2,new TaskStore(context).all().size());assertEquals("You’re done until 11:30 AM! Get some rest. 🪻",TaskWidgetProvider.emptyMessage(context,"","Visibility QA"));assertEquals(context.getString(R.string.widget_empty),TaskWidgetProvider.emptyMessage(context,"","Other label"));
        long reveal=LocalDate.parse(date).atTime(11,30).atZone(ReminderPlanner.ZONE).toInstant().toEpochMilli();assertEquals(reveal,TaskReminders.prefs(context).getLong("visibilityAt",0));String before=store.readState();ShadowSystemClock.advanceBy(Duration.ofMillis(reveal-System.currentTimeMillis()-1));assertEquals(0,TaskWidgetProvider.todayTasks(context,"","Visibility QA").size());ShadowSystemClock.advanceBy(Duration.ofMillis(1));new ReminderReceiver().onReceive(context,new Intent(TaskReminders.VISIBILITY));assertEquals(before,store.readState());assertEquals(1,TaskWidgetProvider.todayTasks(context,"","Visibility QA").size());assertEquals(0,Shadows.shadowOf(context.getSystemService(NotificationManager.class)).size());store.completeTask("html:later:"+date);assertEquals("You’re done until 12:30 PM! Get some rest. 🪻",TaskWidgetProvider.emptyMessage(context,"","Visibility QA"));
    }
    @Test public void currentDefinitionOverridesStaleVisibilityAndActiveTasksStayVisible()throws Exception{
        JSONObject a=task("hidden","12:00 PM",0);store.writeState(new JSONObject().put("customTasks",new JSONArray().put(a)).toString());store.updateSnapshot(new JSONArray().put(record(a)).toString());assertTrue(TaskWidgetProvider.todayTasks(context,"","").isEmpty());JSONObject state=new JSONObject(store.readState());a.remove("showBeforeMinutes");state.put("customTasks",new JSONArray().put(a));store.writeState(state.toString());assertEquals(1,TaskWidgetProvider.todayTasks(context,"","").size());a.put("showBeforeMinutes",0);state.put("customTasks",new JSONArray().put(a)).put("inProgressTasks",new JSONArray().put("hidden:"+date)).put("inProgress","hidden:"+date);store.writeState(state.toString());store.updateSnapshot(new JSONArray().put(record(a)).toString());assertEquals(1,TaskWidgetProvider.todayTasks(context,"","").size());assertEquals(TaskStore.IN_PROGRESS,TaskWidgetProvider.todayTasks(context,"","").get(0).status);
    }
    @Test public void movedAndRecurringTasksUseOccurrenceDatesWithoutChangingCompletionKeys()throws Exception{
        JSONObject a=task("repeat","12:00 PM",30);a.remove("due");a.put("repeat",new JSONObject().put("start",date).put("unit","day").put("amount",1));JSONObject state=new JSONObject().put("movedTo",new JSONObject().put("repeat:"+date,LocalDate.parse(date).plusDays(2).toString()));long tomorrow=LocalDate.parse(date).plusDays(1).atTime(11,30).atZone(ReminderPlanner.ZONE).toInstant().toEpochMilli();assertEquals(tomorrow,TaskVisibility.next(new JSONArray().put(a),state,now));state.put("completed",new JSONObject().put("repeat:"+LocalDate.parse(date).plusDays(1),true));assertEquals(LocalDate.parse(date).plusDays(2).atTime(11,30).atZone(ReminderPlanner.ZONE).toInstant().toEpochMilli(),TaskVisibility.next(new JSONArray().put(a),state,now));
    }
    @Test public void invalidSettingsAndCompletedTasksDoNotArmVisibilityAlarms()throws Exception{
        JSONObject a=task("invalid","Any time",30);assertTrue(TaskVisibility.visible(a,date,0));a.put("time","12:00 PM").put("showBeforeMinutes",-1);assertTrue(TaskVisibility.visible(a,date,0));a.put("showBeforeMinutes",.5);assertTrue(TaskVisibility.visible(a,date,0));a.put("showBeforeMinutes",0);JSONObject state=new JSONObject().put("customTasks",new JSONArray().put(a)).put("completed",new JSONObject().put("invalid:"+date,true));store.writeState(state.toString());assertEquals(0,TaskReminders.prefs(context).getLong("visibilityAt",-1));a.remove("showBeforeMinutes");state.put("customTasks",new JSONArray().put(a));store.writeState(state.toString());assertEquals(0,TaskReminders.prefs(context).getLong("visibilityAt",-1));assertEquals("You’re all done! Get some rest. 🪻",TaskWidgetProvider.emptyMessage(context,"",""));
    }
}
